def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    appreciation_factor = v2 / v1
    expected_2008 = v2 * appreciation_factor

    return {
        "value": expected_2008,
        "trace": {
            "appreciation_factor": appreciation_factor,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "per share"
            }
        }
    }
